$ErrorActionPreference='Stop';$root='C:\Windows\Temp\dc1-t1105';New-Item -ItemType Directory $root -Force|Out-Null;$source=Join-Path $root 'variant-source.txt';$dest=Join-Path $root 'variant-transfer.txt';Set-Content $source 'benign modified transfer fixture' -Encoding Ascii
$server=Start-Job -ScriptBlock {param($file)$l=[Net.HttpListener]::new();$l.Prefixes.Add('http://127.0.0.1:18766/');$l.Start();try{$c=$l.GetContext();$b=[IO.File]::ReadAllBytes($file);$c.Response.ContentLength64=$b.Length;$c.Response.OutputStream.Write($b,0,$b.Length);$c.Response.Close()}finally{$l.Stop();$l.Close()}} -ArgumentList $source
try{Start-Sleep 2;Invoke-WebRequest -Uri 'http://127.0.0.1:18766/variant.txt' -OutFile $dest -UseBasicParsing;if(-not(Wait-Job $server -Timeout 30)){throw 'server timeout'};if(-not(Test-Path $dest)){throw 'destination missing'};$sourceHash=(Get-FileHash $source).Hash;$destinationHash=(Get-FileHash $dest).Hash;if($sourceHash -ne $destinationHash){throw 'transfer hash mismatch'};[pscustomobject]@{SourceHash=$sourceHash;DestinationHash=$destinationHash;Completed=$true}|ConvertTo-Json -Compress|Set-Content (Join-Path $root 'variant.json')}finally{Get-Job|Stop-Job -ErrorAction SilentlyContinue;Get-Job|Remove-Job -Force -ErrorAction SilentlyContinue}
